import{_ as e,H as o,f as s,i as d}from"./chunks/framework.Cvt1eIE0.js";const p=JSON.parse('{"title":"芒伊木 Wiki 名词自动 Icon 转换插件与首版排版设计规格说明","description":"","frontmatter":{},"headers":[],"relativePath":"docs/superpowers/specs/2026-05-20-link-icon-plugin-design.md","filePath":"docs/superpowers/specs/2026-05-20-link-icon-plugin-design.md"}'),a={name:"docs/superpowers/specs/2026-05-20-link-icon-plugin-design.md"};function l(c,i,t,h,n,r){return o(),s("div",null,[...i[0]||(i[0]=[d('<h1 id="芒伊木-wiki-名词自动-icon-转换插件与首版排版设计规格说明" tabindex="-1">芒伊木 Wiki 名词自动 Icon 转换插件与首版排版设计规格说明 <a class="header-anchor" href="#芒伊木-wiki-名词自动-icon-转换插件与首版排版设计规格说明" aria-label="Permalink to &quot;芒伊木 Wiki 名词自动 Icon 转换插件与首版排版设计规格说明&quot;">​</a></h1><p>本项目基于 VitePress 构建。为提供极其现代化的 UI/UX 体验，并降低文档日常维护的复杂度，特设计本规范。</p><hr><h2 id="_1-核心目标" tabindex="-1">1. 核心目标 <a class="header-anchor" href="#_1-核心目标" aria-label="Permalink to &quot;1. 核心目标&quot;">​</a></h2><ol><li><strong>书写极简化</strong>：在 Markdown 文档中，书写 <code>[名词]</code>、<code>[**名词**]</code> 或 <code>**[名词]**</code> 时，编译器会自动将其转换为带有对应精致 Icon 和特殊色彩样式的 <code>&lt;DST&gt;</code> 组件。</li><li><strong>零耦合超链地基</strong>：不直接在 Markdown 中硬编码超链接，而是通过自定义编译插件拦截名词并交由前端处理，为未来的一键无缝注入超链奠定坚实地基。</li><li><strong>首版高质感呈现</strong>：将 <code>_RAW_DATA_SOURCE.md</code> 中的“一、 基础属性与常驻机制”内容移植并全新视觉包装至 <code>docs/mechanics/core.md</code>。</li></ol><hr><h2 id="_2-详细技术方案" tabindex="-1">2. 详细技术方案 <a class="header-anchor" href="#_2-详细技术方案" aria-label="Permalink to &quot;2. 详细技术方案&quot;">​</a></h2><h3 id="_2-1-资源同步与重命名" tabindex="-1">2.1 资源同步与重命名 <a class="header-anchor" href="#_2-1-资源同步与重命名" aria-label="Permalink to &quot;2.1 资源同步与重命名&quot;">​</a></h3><ul><li>在 <code>png/</code> 目录下将含空格的文件重命名： <ul><li><code>icon_mem_ beast_mode.png</code> ➔ <code>icon_mem_beast_mode.png</code></li><li><code>icon_mem_ ghost_mode.png</code> ➔ <code>icon_mem_ghost_mode.png</code></li></ul></li><li>将 <code>png/</code> 下所有 <code>icon_*.png</code>（共 31 个图标）及相关图片拷贝至 <code>.vitepress</code> 静态资源目录 <code>public/</code> 下。</li></ul><h3 id="_2-2-强化自定义-markdown-it-插件" tabindex="-1">2.2 强化自定义 Markdown-it 插件 <a class="header-anchor" href="#_2-2-强化自定义-markdown-it-插件" aria-label="Permalink to &quot;2.2 强化自定义 Markdown-it 插件&quot;">​</a></h3><p>在 <code>.vitepress/config.mjs</code> 中自定义编译期语法树解析逻辑。</p><h4 id="核心正则表达式" tabindex="-1">核心正则表达式 <a class="header-anchor" href="#核心正则表达式" aria-label="Permalink to &quot;核心正则表达式&quot;">​</a></h4><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> regex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">(?:</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\*\\*</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\[</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">(</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">)(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">^</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+?</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\1</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\]</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">(?:</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\*\\*</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">(?!</span><span style="--shiki-light:#22863A;--shiki-light-font-weight:bold;--shiki-dark:#85E89D;--shiki-dark-font-weight:bold;">\\(</span><span style="--shiki-light:#032F62;--shiki-dark:#DBEDFF;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">g</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h4 id="解析与转换机制" tabindex="-1">解析与转换机制 <a class="header-anchor" href="#解析与转换机制" aria-label="Permalink to &quot;解析与转换机制&quot;">​</a></h4><p>当在 Markdown 中匹配到该正则时：</p><ol><li>提取组 2 匹配到的纯文本 <code>[名词]</code>。</li><li>对名词进行前后空格及格式清理。</li><li>根据核心名词映射表（如下）查询对应的 <code>icon</code> 简称： <ul><li><code>生命值</code>: <code>&#39;health&#39;</code></li><li><code>饱食度</code>: <code>&#39;hunger&#39;</code></li><li><code>理智值</code> / <code>精神值</code>: <code>&#39;sanity&#39;</code></li><li><code>灵魂值</code> / <code>灵魂池</code>: <code>&#39;soul&#39;</code></li><li><code>狐狸</code> / <code>兽化</code> / <code>[狐狸]（兽化）</code>: <code>&#39;beast&#39;</code></li><li><code>怨灵</code>: <code>&#39;ghost&#39;</code></li><li><code>封印项圈</code> / <code>封印项圈Lv1</code>: <code>&#39;collar&#39;</code></li><li><code>封印项圈Lv2</code>: <code>&#39;collar-lv2&#39;</code></li><li><code>封印项圈Lv3</code>: <code>&#39;collar-lv3&#39;</code></li><li><code>封印项圈Lv4·暗</code> / <code>暗项圈</code>: <code>&#39;collar-lv4-an&#39;</code></li><li><code>封印项圈Lv4·月</code> / <code>月项圈</code>: <code>&#39;collar-lv4-yue&#39;</code></li><li><code>芒式修补工具</code>: <code>&#39;repair&#39;</code></li><li><code>尸体防腐核心</code>: <code>&#39;tomb-upgrader&#39;</code></li><li><code>芒芒的尸体</code> / <code>尸体</code>: <code>&#39;corpse&#39;</code></li><li><code>暗影观察者</code>: <code>&#39;shadow-gestalt&#39;</code></li></ul></li><li>若匹配成功，输出 <code>&lt;DST icon=&quot;映射后的简称&quot;&gt;名词&lt;/DST&gt;</code>；若映射表未命中，则回退输出 <code>&lt;DST icon=&quot;mod&quot;&gt;名词&lt;/DST&gt;</code>。</li><li>保证标准的 Markdown 链接 <code>[文字](url)</code> 保持完整不受干扰。</li></ol><h3 id="_2-3-升级-dst-组件与全局样式" tabindex="-1">2.3 升级 <code>&lt;DST&gt;</code> 组件与全局样式 <a class="header-anchor" href="#_2-3-升级-dst-组件与全局样式" aria-label="Permalink to &quot;2.3 升级 `&lt;DST&gt;` 组件与全局样式&quot;">​</a></h3><p>在 <code>DST.vue</code> 中扩展以下功能：</p><ul><li>完整支持所有 <code>icon</code> 映射和回退通用图标。</li><li>采用 Glassmorphism（毛玻璃）卡片包边，字体配置 DST 经典的 HSL 炫彩发光效果。</li><li>增加 Hover 轻微位移与亮化微动效。</li></ul><h3 id="_2-4-重构一号板块-docs-mechanics-core-md" tabindex="-1">2.4 重构一号板块 <code>docs/mechanics/core.md</code> <a class="header-anchor" href="#_2-4-重构一号板块-docs-mechanics-core-md" aria-label="Permalink to &quot;2.4 重构一号板块 `docs/mechanics/core.md`&quot;">​</a></h3><ul><li>将 <code>_RAW_DATA_SOURCE.md</code> 中“一、 基础属性与常驻机制”内容移植过来。</li><li>将所有涉及核心机制的词汇以 <code>[名词]</code>、<code>[**名词**]</code> 规范化包裹。</li><li>引入现代化的卡片视图对三维属性、已死之人复活惩罚、三形态变化进行可视化重构，拒绝冗长单一的纯文字段落，呈现超流线感的海报化效果。</li></ul><hr><h2 id="_3-验证方案" tabindex="-1">3. 验证方案 <a class="header-anchor" href="#_3-验证方案" aria-label="Permalink to &quot;3. 验证方案&quot;">​</a></h2><ul><li><strong>本地编译验证</strong>：运行 <code>npm run dev</code>，检查有无解析错误。</li><li><strong>页面效果检查</strong>： <ul><li>检查 <code>[生命值]</code> 是否正确带有红心 icon。</li><li>检查不认识的名词如 <code>[再一次的机会]</code> 是否正确带有 <code>icon_mod.png</code> 模组通用 icon。</li><li>检查标准的 Markdown 链接 <code>[VitePress](https://...)</code> 是否依然正常点击，不受自动 icon 转换插件的干扰。</li></ul></li></ul>',24)])])}const g=e(a,[["render",l]]);export{p as __pageData,g as default};
